import { Profiler, useState, ProfilerOnRenderCallback } from 'react';

export type RenderLog = {
  id: string;
  phase: 'mount' | 'update' | 'nested-update';
  actualDuration: number;
};

export function MeasuredCounter({ onRender }: { onRender: (log: RenderLog) => void }) {
  const [count, setCount] = useState<number>(0);

  const handleRender: ProfilerOnRenderCallback = (id, phase, actualDuration) => {
    onRender({ id, phase, actualDuration });
  };

  return (
    <Profiler id="counter" onRender={handleRender}>
      <button onClick={() => setCount((c) => c + 1)}>{count}</button>
    </Profiler>
  );
}
